BEGIN;
DO $test$
DECLARE owner uuid:='b8cbf27e-2391-4fb5-b061-f1488e8c3135';f uuid;k uuid:=gen_random_uuid();d uuid;j uuid;w uuid;token uuid:=gen_random_uuid();q public.quality_reviews;r jsonb;source text:='合成资料：项目处于试点准备阶段，预算尚未确定。';denied boolean;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',owner::text,true);
 denied:=false;BEGIN PERFORM public.create_brief_workflow('BRIEF FIXTURE','生成项目简报','fixture.pdf','pdf_extract_v1',k,false);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Missing model consent accepted';END IF;
 f:=public.create_brief_workflow('BRIEF FIXTURE','根据合成资料生成项目简报','fixture.pdf','pdf_extract_v1',k,true);
 IF public.create_brief_workflow('BRIEF FIXTURE','根据合成资料生成项目简报','fixture.pdf','pdf_extract_v1',k,true)<>f THEN RAISE EXCEPTION 'Creation not idempotent';END IF;
 SELECT document_job_id INTO d FROM public.brief_workflows WHERE id=f;
 denied:=false;BEGIN PERFORM public.submit_brief_workflow(f);EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Missing upload accepted';END IF;
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('company-documents',owner::text||'/'||d::text||'/input','{"size":100}');
 PERFORM public.submit_brief_workflow(f);SELECT plan_job_id INTO j FROM public.brief_workflows WHERE id=f;
 PERFORM public.submit_brief_workflow(f);IF (SELECT plan_job_id FROM public.brief_workflows WHERE id=f)<>j THEN RAISE EXCEPTION 'Duplicate COS job';END IF;
 IF public.advance_brief_workflow(f) THEN RAISE EXCEPTION 'Planned before COS';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=j;
 PERFORM public.complete_chat_reply(j,token,'{"manager_code":"COO","assignment":"由COO员工提取资料并编写项目简报","acceptance":"事实保留S1原文，建议与未知项分开"}','[]');
 PERFORM public.advance_brief_workflow(f);IF (SELECT state FROM public.brief_workflows WHERE id=f)<>'extracting' THEN RAISE EXCEPTION 'COS did not route tools';END IF;
 -- Synthetic adapter completion: the real container is covered separately by the 10 fixture tests.
 UPDATE public.document_jobs SET state='succeeded',finished_at=now(),result=jsonb_build_object('output_sha256',encode(sha256(convert_to(source,'UTF8')),'hex')) WHERE id=d;
 PERFORM public.advance_brief_workflow(f,'tampered');IF (SELECT state FROM public.brief_workflows WHERE id=f)<>'blocked' THEN RAISE EXCEPTION 'Tampered source accepted';END IF;
 UPDATE public.brief_workflows SET state='extracting',last_error=NULL WHERE id=f;
 PERFORM public.advance_brief_workflow(f,source);SELECT work_order_id INTO w FROM public.brief_workflows WHERE id=f;
 IF w IS NULL OR public.advance_brief_workflow(f,source) THEN RAISE EXCEPTION 'Execution not idempotent';END IF;
 SELECT (result->>'current_job_id')::uuid INTO j FROM public.tasks WHERE id=w;
 IF (SELECT input->>'brief_flow_id' FROM public.tasks WHERE id=j)<>f::text THEN RAISE EXCEPTION 'Specialized employee binding missing';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=j;
 PERFORM public.complete_chat_reply(j,token,'合成项目简报。资料事实：项目处于试点准备阶段。建议：确认客户。待确认：预算。','[]');
 SELECT * INTO q FROM public.quality_reviews WHERE source_job_id=j;
 IF q.id IS NULL OR q.snapshot->'brief_source'->>'text' IS DISTINCT FROM source OR q.employee_id::text=(SELECT input->>'employee_id' FROM public.tasks WHERE id=w) THEN RAISE EXCEPTION 'Missing independent source review';END IF;
 r:='{"verdict":"needs_human","summary":"需核实","checks":[{"id":"task_goal","status":"not_checked","evidence":"","reason":"需核实"},{"id":"task_acceptance","status":"not_checked","evidence":"","reason":"需核实"},{"id":"truthfulness","status":"not_checked","evidence":"","reason":"需核实"}]}';
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q.job_id;
 PERFORM public.complete_chat_reply(q.job_id,token,r::text,'[]');
 denied:=false;BEGIN PERFORM public.review_work_order(w,j,'accept','合成测试人工说明超过二十字，仍不允许绕过本任务的独立质检通过门禁。');EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Uncertain brief accepted';END IF;
 PERFORM public.review_work_order(w,j,'revise','请补齐原文引用后重新质检');SELECT (result->>'current_job_id')::uuid INTO j FROM public.tasks WHERE id=w;
 IF (SELECT input->>'brief_flow_id' FROM public.tasks WHERE id=j)<>f::text THEN RAISE EXCEPTION 'Revision lost source binding';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=j;
 PERFORM public.complete_chat_reply(j,token,'合成项目简报。资料事实：项目处于试点准备阶段。原文：项目处于试点准备阶段。建议：确认客户。待确认：预算。','[]');
 SELECT * INTO q FROM public.quality_reviews WHERE source_job_id=j;
 IF q.snapshot->'brief_source'->>'text' IS DISTINCT FROM source THEN RAISE EXCEPTION 'Revision review lost source';END IF;
 r:='{"verdict":"pass","summary":"合成测试通过，待CEO验收","checks":[{"id":"task_goal","status":"pass","evidence":"合成项目简报。","reason":"有简报"},{"id":"task_acceptance","status":"pass","evidence":"原文：项目处于试点准备阶段。","reason":"包含原文"},{"id":"truthfulness","status":"pass","evidence":"建议：确认客户。","reason":"建议已标注"}]}';
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q.job_id;
 PERFORM public.complete_chat_reply(q.job_id,token,r::text,'[]');
 IF (SELECT result->>'review_state' FROM public.tasks WHERE id=w)='accepted' THEN RAISE EXCEPTION 'AI performed CEO acceptance';END IF;
 PERFORM public.review_work_order(w,j,'accept','仅限事务内合成验收测试');
 IF (SELECT result->>'review_state' FROM public.tasks WHERE id=w)<>'accepted' THEN RAISE EXCEPTION 'CEO acceptance failed';END IF;
 IF has_table_privilege('authenticated','public.brief_workflows','UPDATE') OR has_function_privilege('authenticated','public.advance_brief_workflow(uuid,text)','EXECUTE') OR has_function_privilege('service_role','private.queue_brief_document(uuid,uuid)','EXECUTE') OR has_function_privilege('anon','public.create_brief_workflow(text,text,text,text,uuid,boolean)','EXECUTE') THEN RAISE EXCEPTION 'Excess workflow privilege';END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 denied:=false;BEGIN PERFORM public.submit_brief_workflow(f);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign actor accepted';END IF;
END $test$;
SET LOCAL ROLE authenticated;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.brief_workflows) THEN RAISE EXCEPTION 'Foreign workflow leaked';END IF;END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: consent, upload, COS assignment, tool routing, tamper gate, idempotency, employee and independent inspector separation, revision provenance, strict CEO acceptance, privilege and RLS; synthetic fixtures rolled back' AS checks;
